from functools import wraps

def log(f):
    @wraps(f)
    def inner(*a, **k):
        return f(*a, **k)
    return inner

@log
def add(x, y):
    "adds"
    return x + y

print(add.__name__, add.__doc__, add(1, 2))

def counted(f):
    def inner(*a):
        inner.calls += 1
        return f(*a)
    inner.calls = 0
    return inner

@counted
def sq(x):
    return x * x

sq(2)
sq(3)
print(sq.calls, sq.__name__)

def deco(f):
    def inner(*args):
        return f(*args)

@deco
def hi():
    return "hi"

def repeat(times):
    def deco(f):
        def inner(*args):
            for _ in range(times):
                f(*args)
        return inner
    return deco

@repeat
def hi():
    print("hi")

def memoize(f):
    cache = {}
    def inner(n):
        if n not in cache:
            cache[n] = f(n)
        return cache[n]
    return inner

@memoize
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)
